CREATE SCHEMA KERVYN

CREATE TABLE KERVYN.PRODUCT (
    PRODUCT_ID       INTEGER,
    PRODUCT_CODE     VARCHAR(50),
    PRODUCT_NAME     VARCHAR(150),
    REVISION         VARCHAR(20),
    CREATED_AT       TIMESTAMP
);

CREATE TABLE KERVYN.PROCESS_STAGE (
    STAGE_ID         INTEGER,
    STAGE_NAME       VARCHAR(100),
    STAGE_SEQUENCE   INTEGER,
    STAGE_CATEGORY   VARCHAR(50)
);

CREATE TABLE KERVYN.DEFECT_TYPE (
    DEFECT_ID        INTEGER,
    DEFECT_CODE      VARCHAR(40),
    DEFECT_NAME      VARCHAR(150),
    DEFECT_CATEGORY  VARCHAR(80),
    SEVERITY         VARCHAR(20)
);

CREATE TABLE KERVYN.MACHINE (
    MACHINE_ID       INTEGER,
    MACHINE_CODE     VARCHAR(50),
    MACHINE_TYPE     VARCHAR(80),
    LINE_ID          VARCHAR(40),
    LOCATION         VARCHAR(100)
);

-- ============================================
-- 2. PRODUCTION TRACEABILITY
-- ============================================

CREATE TABLE KERVYN.WORK_ORDER (
    WORK_ORDER_ID    BIGINT,
    WORK_ORDER_CODE  VARCHAR(60),
    PRODUCT_ID       INTEGER,
    PLANNED_QTY      INTEGER,
    STARTED_AT       TIMESTAMP,
    COMPLETED_AT     TIMESTAMP,
    ORDER_STATUS     VARCHAR(30)
);

CREATE TABLE KERVYN.BOARD_UNIT (
    BOARD_ID         BIGINT,
    SERIAL_NUMBER    VARCHAR(100),
    WORK_ORDER_ID    BIGINT,
    PRODUCT_ID       INTEGER,
    REVISION         VARCHAR(20),
    CREATED_AT       TIMESTAMP,
    CURRENT_STATUS   VARCHAR(30)
);

-- ============================================
-- 3. PROCESS HISTORY
-- One row per board per processing event
-- ============================================

CREATE TABLE KERVYN.PROCESS_EVENT (
    EVENT_ID         BIGINT,
    BOARD_ID         BIGINT,
    STAGE_ID         INTEGER,
    MACHINE_ID       INTEGER,
    EVENT_TIME       TIMESTAMP,
    OPERATOR_ID      VARCHAR(50),
    LOT_CODE         VARCHAR(80),
    TEMPERATURE_C    DECIMAL(10,3),
    PROCESS_DURATION_SEC DECIMAL(12,3),
    PARAMETER_JSON   VARCHAR(2000),
    EVENT_STATUS     VARCHAR(30)
);

-- ============================================
-- 4. INSPECTION AND TEST RESULTS
-- ============================================

CREATE TABLE KERVYN.INSPECTION_RESULT (
    INSPECTION_ID BIGINT,
    BOARD_ID BIGINT,
    STAGE_ID INTEGER,
    MACHINE_ID INTEGER,
    INSPECTION_TIME TIMESTAMP,
    INSPECTION_TYPE VARCHAR(60),
    INSPECTION_STATUS VARCHAR(20),
    MEASURED_VALUE DECIMAL(18,6),
    MEASUREMENT_UNIT VARCHAR(30),
    LOWER_LIMIT DECIMAL(18,6),
    UPPER_LIMIT DECIMAL(18,6),
    TEST_CODE VARCHAR(60),
    TEST_DETAILS VARCHAR(2000)
);


-- ============================================
-- 5. DEFECT RECORDS
-- Discovery location is not necessarily
-- the actual origin of the defect.
-- ============================================

CREATE TABLE KERVYN.DEFECT_EVENT (
    DEFECT_EVENT_ID  BIGINT,
    BOARD_ID         BIGINT,
    INSPECTION_ID    BIGINT,
    DEFECT_ID        INTEGER,
    DETECTED_STAGE_ID INTEGER,
    SUSPECTED_ORIGIN_STAGE_ID INTEGER,
    CONFIRMED_ORIGIN_STAGE_ID INTEGER,
    DETECTED_AT      TIMESTAMP,
    DEFECT_COUNT     INTEGER,
    SEVERITY         VARCHAR(20),
    ROOT_CAUSE_STATUS VARCHAR(30),
    ROOT_CAUSE_NOTES VARCHAR(2000),
    DISPOSITION      VARCHAR(30)
);

-- ============================================
-- 6. REWORK AND RETEST
-- ============================================

CREATE TABLE KERVYN.REWORK_EVENT (
    REWORK_ID        BIGINT,
    BOARD_ID         BIGINT,
    DEFECT_EVENT_ID  BIGINT,
    REWORK_STAGE_ID  INTEGER,
    REWORK_TIME      TIMESTAMP,
    ACTION_TAKEN     VARCHAR(500),
    REWORK_COST      DECIMAL(12,2),
    RETEST_RESULT    VARCHAR(20),
    CLOSED_AT        TIMESTAMP
);


-- KERVYN PCBA Quality Intelligence - synthetic demo dataset
-- Exasol SQL. All records are synthetic and for demonstration only.
-- Assumes tables already exist. INSPECTION_RESULT column is INSPECTION_STATUS.
-- Run once; IDs are explicit and references are designed to match.

-- MASTER DATA

-- WORK ORDERS

-- BOARD UNITS: 60 boards across three work orders

-- PROCESS EVENTS: stages 1 through 9 for each board; some reach stage 10

-- INSPECTION RESULTS: incoming inspection, AOI, firmware verification, final test

-- DEFECT EVENTS: mix of final-line discoveries and upstream catches

-- REWORK EVENTS: linked to rework disposition defects

-- VALIDATION COUNTS
SELECT COUNT(*) AS PRODUCTS FROM KERVYN.PRODUCT;
SELECT COUNT(*) AS STAGES FROM KERVYN.PROCESS_STAGE;
SELECT COUNT(*) AS DEFECT_TYPES FROM KERVYN.DEFECT_TYPE;
SELECT COUNT(*) AS MACHINES FROM KERVYN.MACHINE;
SELECT COUNT(*) AS WORK_ORDERS FROM KERVYN.WORK_ORDER;
SELECT COUNT(*) AS BOARDS FROM KERVYN.BOARD_UNIT;
SELECT COUNT(*) AS PROCESS_EVENTS FROM KERVYN.PROCESS_EVENT;
SELECT COUNT(*) AS INSPECTIONS FROM KERVYN.INSPECTION_RESULT;
SELECT COUNT(*) AS DEFECT_EVENTS FROM KERVYN.DEFECT_EVENT;
SELECT COUNT(*) AS REWORK_EVENTS FROM KERVYN.REWORK_EVENT;

-- Example analytics: defect distribution at final functional testing
SELECT dt.DEFECT_NAME, COUNT(*) AS DEFECT_OCCURRENCES, COUNT(DISTINCT de.BOARD_ID) AS AFFECTED_BOARDS
FROM KERVYN.DEFECT_EVENT de
JOIN KERVYN.DEFECT_TYPE dt ON dt.DEFECT_ID = de.DEFECT_ID
WHERE de.DETECTED_STAGE_ID = 9
GROUP BY dt.DEFECT_NAME
ORDER BY AFFECTED_BOARDS DESC;
